//! The Concordia theme constants as gpui types (M28 E28-5, D05, D101).
//!
//! `aegis-concordia` holds one constant per token of
//! `ui/concordia-tokens/concordia-tokens.css`, generated by
//! `tools/concordia_theme.py`; which toolkit type a constant becomes is this
//! module's business. It is the only file in the crate that builds a gpui
//! colour: `tests/theme.rs` refuses a colour literal anywhere else, so every
//! colour the shell paints comes from the token file.

use aegis_concordia::{Rgb, tokens};
use gpui::{Rgba, rgb};

/// The gpui colour of an opaque Concordia colour token.
#[must_use]
pub fn color(token: Rgb) -> Rgba {
    rgb(u32::from_be_bytes([0, token.red, token.green, token.blue]))
}

/// The background of the shell's surfaces: `--concordia-color-surface`.
#[must_use]
pub fn surface() -> Rgba {
    color(tokens::COLOR_SURFACE)
}
